PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS people(id TEXT PRIMARY KEY,name TEXT NOT NULL COLLATE NOCASE UNIQUE,seen TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,person TEXT NOT NULL REFERENCES people(id),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS dishes(id TEXT PRIMARY KEY,name TEXT NOT NULL COLLATE NOCASE UNIQUE,icon TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS items(id TEXT PRIMARY KEY,name TEXT NOT NULL COLLATE NOCASE UNIQUE,icon TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('ingredient','prep')),unit TEXT NOT NULL,location TEXT NOT NULL DEFAULT '',known INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 0,lead REAL,threshold REAL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS dish_items(dish TEXT REFERENCES dishes(id),item TEXT REFERENCES items(id),PRIMARY KEY(dish,item));
CREATE TABLE IF NOT EXISTS components(parent TEXT REFERENCES items(id),child TEXT REFERENCES items(id),PRIMARY KEY(parent,child),CHECK(parent!=child));
CREATE TABLE IF NOT EXISTS batches(id TEXT PRIMARY KEY,item TEXT NOT NULL REFERENCES items(id),qty REAL NOT NULL CHECK(qty>=0),location TEXT NOT NULL,received TEXT NOT NULL,opened TEXT,use_by TEXT);
CREATE TABLE IF NOT EXISTS services(day TEXT PRIMARY KEY,expected INTEGER,actual INTEGER,phase TEXT NOT NULL DEFAULT 'live');
CREATE TABLE IF NOT EXISTS movements(id TEXT PRIMARY KEY,item TEXT NOT NULL REFERENCES items(id),batch TEXT REFERENCES batches(id),kind TEXT NOT NULL,delta REAL NOT NULL,balance REAL NOT NULL,day TEXT NOT NULL,person TEXT NOT NULL REFERENCES people(id),note TEXT NOT NULL DEFAULT '',created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS predictions(id TEXT PRIMARY KEY,item TEXT NOT NULL REFERENCES items(id),qty REAL NOT NULL,services REAL NOT NULL,source TEXT NOT NULL,day TEXT NOT NULL,person TEXT NOT NULL REFERENCES people(id),outcome REAL,outcome_day TEXT,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,item TEXT REFERENCES items(id),kind TEXT NOT NULL CHECK(kind IN ('buy','prep')),body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',person TEXT REFERENCES people(id),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS concerns(id TEXT PRIMARY KEY,body TEXT NOT NULL,message TEXT NOT NULL,item TEXT REFERENCES items(id),location TEXT NOT NULL DEFAULT '',person TEXT NOT NULL REFERENCES people(id),owner TEXT REFERENCES people(id),status TEXT NOT NULL DEFAULT 'open',resolution TEXT NOT NULL DEFAULT '',created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activity(seq INTEGER PRIMARY KEY AUTOINCREMENT,person TEXT NOT NULL REFERENCES people(id),kind TEXT NOT NULL,message TEXT NOT NULL,ref TEXT,day TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS answers(id TEXT PRIMARY KEY,person TEXT NOT NULL REFERENCES people(id),ref TEXT,question TEXT NOT NULL,answer TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS drafts(id TEXT PRIMARY KEY,person TEXT REFERENCES people(id),kind TEXT NOT NULL,body TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requests(id TEXT PRIMARY KEY,person TEXT NOT NULL REFERENCES people(id),payload TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS movements_item_day ON movements(item,day);
CREATE INDEX IF NOT EXISTS batches_item ON batches(item);
PRAGMA user_version=1;
CREATE TABLE IF NOT EXISTS shift_details(day TEXT PRIMARY KEY REFERENCES services(day),reservations INTEGER,walkins INTEGER,rush TEXT NOT NULL DEFAULT '',weather TEXT NOT NULL DEFAULT '',terrace TEXT NOT NULL DEFAULT '',prep TEXT NOT NULL DEFAULT '',tags TEXT NOT NULL DEFAULT '[]',events TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',person TEXT NOT NULL REFERENCES people(id),version INTEGER NOT NULL DEFAULT 1,updated TEXT NOT NULL);
PRAGMA user_version=2;
